  function queueActions(job) { if(job.state === "scheduled") return ["pause"]; if(job.state === "approved") return job.reason === "official-api-ready" ? ["schedule","cancel"] : ["manual","cancel"]; if(job.state === "failed") return ["retry","cancel"]; if(job.state === "retry-scheduled") return job.reason === "official-api-ready" ? ["resume","pause"] : ["pause","cancel"]; if(job.state === "draft") return ["review","cancel"]; if(job.state === "awaiting-review") return ["approve","reject","cancel"]; return []; }

