    const zoom=pref.zoom==="fit"?1:Math.max(.35,Math.min(1.5,Number(pref.zoom)||1)),quality=effectivePreviewQuality();
    consoleNode.dataset.previewBg=pref.background;consoleNode.classList.toggle("is-safe",Boolean(pref.safeZone));consoleNode.classList.toggle("is-comparing",Boolean(pref.compare));consoleNode.classList.toggle("is-motion-off",!pref.motion);consoleNode.classList.toggle("is-quality-economy",quality==="economy");
