    app.host.querySelector("[data-smt2-preview-safe]")?.setAttribute("aria-pressed",String(Boolean(pref.safeZone)));app.host.querySelector("[data-smt2-preview-compare]")?.setAttribute("aria-pressed",String(Boolean(pref.compare)));app.host.querySelector("[data-smt2-preview-motion]")?.setAttribute("aria-pressed",String(Boolean(pref.motion)));
