  const assetDb=()=>new Promise((resolve,reject)=>{if(!root.indexedDB)return reject(new Error("IndexedDB không được hỗ trợ."));const open=indexedDB.open("hh-social-media-assets-v1",1);open.onupgradeneeded=()=>open.result.createObjectStore("assets");open.onsuccess=()=>resolve(open.result);open.onerror=()=>reject(open.error);});
