  const assetKey=(asset)=>`${app.state.project.ownerId}:${app.state.workspaceId}:${asset.id}`;
  async function sanitizeAsset(file,mime){if(mime!=="image/svg+xml")return file;const parsed=new DOMParser().parseFromString(await file.text(),"image/svg+xml");if(parsed.querySelector("parsererror,script,foreignObject,iframe,object,embed"))throw new Error("SVG chứa thành phần không an toàn.");parsed.querySelectorAll("*").forEach((node)=>[...node.attributes].forEach((attr)=>{if(/^on/i.test(attr.name)||/^(?:javascript|data:text\/html)/i.test(attr.value))node.removeAttribute(attr.name);if(["href","xlink:href"].includes(attr.name)&&!attr.value.startsWith("#"))node.removeAttribute(attr.name);}));return new Blob([new XMLSerializer().serializeToString(parsed.documentElement)],{type:mime});}
  async function addFiles(files){let added=0;const existing=new Set(app.state.project.assets.map(a=>a.sha256));for(const file of [...files].slice(0,100)){const hardLimit=file.type.startsWith("video/")?2*1024*1024*1024:50*1024*1024;if(file.size>hardLimit){toast(`${file.name} vượt giới hạn an toàn.`,"warn");continue;}const check=await Core().detectMime(file);if(!check.allowed){toast(`${file.name}: loại file không khớp nội dung.`,"warn");continue;}try{const blob=await sanitizeAsset(file,check.detected),sha=await Core().sha256(await blob.arrayBuffer());if(existing.has(sha)){toast(`${file.name}: đã bỏ qua file trùng checksum.`,"warn");continue;}const meta=await Pipeline().inspectFile(blob),asset={id:`asset-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,name:Core().filename(file.name,file.name.split(".").pop()),mimeType:check.detected,size:blob.size,sha256:sha,sourceType:"user-upload",rightsConfirmed:false,commercialUseConfirmed:false,thirdPartyElementsReviewed:false,metadata:meta,url:URL.createObjectURL(blob)};await assetRecord("put",assetKey(asset),blob);await Pipeline().createCheckpoint({asset,meta,ownerId:app.state.project.ownerId,workspaceId:app.state.workspaceId});app.state.project.assets.push(asset);existing.add(sha);added++;}catch(error){toast(`${file.name}: ${error.message}`,"warn");}}updateProject({assets:app.state.project.assets,activeAsset:Math.max(0,app.state.project.assets.length-added)},"Thêm asset");rerender();toast(`Đã thêm ${added} file; cần xác nhận quyền trước khi xuất bản.`);}
  async function hydrateAssets(){for(const asset of app.state.project.assets)if(!asset.url)try{const blob=await assetRecord("get",assetKey(asset));if(blob)asset.url=URL.createObjectURL(blob);}catch{}renderAssets();}

  async function saveCloud(){if(!app.options.currentUser?.id)return null;const p=app.state.project;return request(`projects?workspaceId=${encodeURIComponent(app.state.workspaceId)}`,{method:"POST",body:JSON.stringify({workspaceId:app.state.workspaceId,projectId:p.id,title:p.title,toolId:p.toolId,platform:p.platform,payload:{caption:p.caption,altText:p.altText,ratio:p.ratio,theme:p.theme,assets:p.assets.map(({url,...asset})=>asset)}})});}
