  async function startOAuth(provider){if(!app.options.currentUser?.id)throw new Error("Hãy đăng nhập HH Platform trước khi kết nối tài khoản.");const endpoints={facebook:"/api/facebook/oauth/start",tiktok:"/api/tiktok/oauth/start",youtube:"/api/youtube/oauth/start"},body={returnTo:location.origin,returnHash:"#/social-media-tools"};if(provider==="tiktok")body.scopes=["user.info.basic","user.info.profile","user.info.stats","video.list","video.upload","video.publish"];if(provider==="youtube")body.permissionPreset="creator";const response=await fetch(endpoints[provider],{method:"POST",credentials:"include",cache:"no-store",headers:{"Content-Type":"application/json",...(root.HHAuthSession?.token?.()?{Authorization:`Bearer ${root.HHAuthSession.token()}`}:{})},body:JSON.stringify(body)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Không thể bắt đầu OAuth ${provider}.`);const allowed={facebook:/^https:\/\/(?:www\.)?facebook\.com\//i,tiktok:/^https:\/\/(?:www\.)?tiktok\.com\//i,youtube:/^https:\/\/accounts\.google\.com\//i};if(!allowed[provider].test(data.authorizeUrl||""))throw new Error("Nhà cung cấp không trả về URL OAuth hợp lệ.");sessionStorage.setItem("hh.social.oauth.pending",JSON.stringify({provider,workspaceId:app.state.workspaceId,startedAt:Date.now()}));location.assign(data.authorizeUrl);}

  function unicodeStyle(value, style="bold") {
    const styles={ bold:[0x1d5d4,0x1d5ee,0x1d7ec], mono:[0x1d670,0x1d68a,0x1d7f6], circle:[0x24b6,0x24d0,0x2460] },points=styles[style]||styles.bold;
    return [...String(value||"")].map((char)=>{const code=char.codePointAt(0);if(code>=65&&code<=90)return String.fromCodePoint(points[0]+code-65);if(code>=97&&code<=122)return String.fromCodePoint(points[1]+code-97);if(code>=49&&code<=57)return String.fromCodePoint(points[2]+code-49);if(code===48&&style!=="circle")return String.fromCodePoint(points[2]+9);return char;}).join("");
  }
  async function paletteFromActiveAsset() {
    const asset=app.state.project.assets[app.state.project.activeAsset||0]; if(!asset?.url||!asset.mimeType.startsWith("image/"))throw new Error("Hãy tải và chọn một ảnh trước.");
    const image=await loadImage(asset.url),canvas=document.createElement("canvas"),ctx=canvas.getContext("2d",{willReadFrequently:true});canvas.width=64;canvas.height=64;ctx.drawImage(image,0,0,64,64);const data=ctx.getImageData(0,0,64,64).data,colors=new Map();
    for(let index=0;index<data.length;index+=16){if(data[index+3]<128)continue;const rgb=[data[index],data[index+1],data[index+2]].map((value)=>Math.min(255,Math.round(value/32)*32)),key=rgb.map((value)=>value.toString(16).padStart(2,"0")).join("").toUpperCase();colors.set(key,(colors.get(key)||0)+1);}
    return [...colors.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5).map(([hex])=>`#${hex}`);
  }
