  async function exportResult(format){if(!app.lastResult)throw new Error("Chưa có kết quả để xuất.");const tool=activeTool(),result=app.lastResult.result,name=Core().slug(`${tool.name}-${new Date().toISOString().slice(0,10)}`);if(format==="json")return saveBlob(new Blob([JSON.stringify(result,null,2)],{type:"application/json"}),`${name}.json`);if(format==="csv"){const value=result.csv||Engines().toCsv([["result"],[app.lastResult.text]]);return saveBlob(new Blob([value],{type:"text/csv;charset=utf-8"}),`${name}.csv`);}if(format==="txt")return saveBlob(new Blob([app.lastResult.text],{type:"text/plain;charset=utf-8"}),`${name}.txt`);if(format==="qr"){if(!root.QRCode?.toCanvas)throw new Error("Bộ tạo QR local chưa sẵn sàng.");const canvas=document.createElement("canvas");await root.QRCode.toCanvas(canvas,result.qrPayload||app.lastResult.text,{width:512,margin:2,color:{dark:"#07131fff",light:"#ffffffff"}});return saveBlob(await new Promise(resolve=>canvas.toBlob(resolve,"image/png")),`${name}-qr.png`);}if(["png","webp"].includes(format))return downloadImage();if(format==="zip")return exportKit();throw new Error(`Định dạng ${format.toUpperCase()} chưa hỗ trợ trong workspace này.`);}
