  function validateActiveTool(){const check=Contracts().validate(activeTool(),app.state.project,contractContext()),out=app.host.querySelector("[data-smt2-output]");out.textContent=check.valid?`✓ Đầu vào ${activeTool().name} hợp lệ.\nCó thể chạy processor ${Contracts().contractFor(activeTool(),contractContext()).processor}.`:`Cần sửa ${check.errors.length} lỗi:\n${check.errors.map((item)=>`• ${item.message}`).join("\n")}`;toast(check.valid?"Dữ liệu hợp lệ.":"Đầu vào chưa hợp lệ.",check.valid?"":"warn");return check.valid;}
  async function runCapability(handler){if(handler==="validate")return validateActiveTool();if(handler==="run")return runTool();if(handler==="apply")return applyResult();if(handler==="preview"){app.previewRuntime.flush();renderPreviewNow();toast("Preview đã đồng bộ tức thì.");return;}if(handler==="download")return downloadImage();if(handler==="variants")return exportMediaVariants();if(handler==="connect"){const tool=activeTool();if(tool.mode==="provider")location.hash=`#${connectRoute(tool)}`;else app.host.querySelector("[data-smt2-accounts]")?.click();return;}if(handler==="package")return exportKit();if(handler==="export"||handler.startsWith("export:")){const requested=handler.split(":")[1],allowed=Contracts().contractFor(activeTool(),contractContext()).exports,format=requested&&allowed.includes(requested)?requested:allowed[0]||"txt";return exportResult(format);}throw new Error(`Tác vụ ${handler} chưa được ánh xạ.`);}
  function socialPostResult(tool,p){const provider=tool.id.includes("threads")?"threads":tool.id.includes("x-")||tool.id==="tweet-card"?"x":platformFor(tool),stats=Core().captionStats(p.caption,provider),limits={instagram:2200,facebook:63206,tiktok:2200,x:280,threads:500,linkedin:3000,pinterest:500,reddit:40000,telegram:4096,discord:2000};const limit=limits[provider]||stats.limit;const parts=["x-composer","threads-composer"].includes(tool.id)?Core().splitThread(p.caption,provider):[p.caption];return{toolId:tool.id,provider,variant:tool.id,output:`${tool.name}\nNền tảng: ${provider}\nBiến thể: ${tool.id}\nTỷ lệ: ${p.ratio}\nAsset: ${p.assets.length}\nKý tự: ${stats.characters}/${limit}\nHashtag: ${stats.hashtags.length}\nSố phần: ${parts.length}\n\n${parts.map((part,index)=>parts.length>1?`[${index+1}/${parts.length}] ${part}`:part).join("\n\n")}`,parts,platform:provider,ratio:p.ratio,limit,valid:stats.characters<=limit,assets:p.assets.map(({url,...asset})=>asset),apply:{platform:provider,caption:parts.join("\n\n")}};}
